-- Add fabric-scoped approvals without changing existing full-colour approvals.
CREATE TABLE IF NOT EXISTS ekwl_rfd_fabric_color_mappings (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,scope_key CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,ewo CHAR(6) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,source_name VARCHAR(16) CHARACTER SET ascii NOT NULL,from_color TEXT NOT NULL,to_color TEXT NOT NULL,fabric_details TEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,revision INT UNSIGNED NOT NULL DEFAULT 1,approved_by CHAR(36) NOT NULL,approved_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),source_digest CHAR(64) CHARACTER SET ascii NOT NULL,KEY ekwl_fabric_color_mapping_ewo (ewo,is_active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
